request.query:
query SearchResources($query: String, $cursor: String) {
            collections(first: 50, after: $cursor, query: $query) {
              pageInfo { hasNextPage endCursor }
              edges {
                node {
                  id
                  title
                  handle
                  contentStatus: metafield(namespace: "custom", key: "content_status") { value }
                  summary: metafield(namespace: "custom", key: "summary") { value }
                  secondarySignal: metafield(namespace: "custom", key: "intro_text") { value }
                }
              }
            }
          }
